  1→package jlsm.table.internal;
  2→
  3→import java.security.GeneralSecurityException;
  4→import java.util.Arrays;
  5→import java.util.Objects;
  6→
  7→import javax.crypto.Cipher;
  8→import javax.crypto.spec.SecretKeySpec;
  9→
 10→/**
 11→ * Contract: Deterministic encryption using AES-SIV (RFC 5297). A 512-bit key is split into K1 (CMAC
 12→ * key) and K2 (CTR key). S2V derives a synthetic IV from the plaintext and optional associated
 13→ * data; AES-CTR encrypts the plaintext under that IV. The same plaintext + associated data always
 14→ * produces the same ciphertext, enabling equality queries on encrypted values.
 15→ *
 16→ * <p>
 17→ * Ciphertext format: {@code [16-byte IV || ciphertext]} — +16 bytes expansion.
 18→ *
 19→ * <p>
 20→ * Governed by: .kb/algorithms/encryption/searchable-encryption-schemes.md
 21→ */
 22→public final class AesSivEncryptor {
 23→
 24→    private static final int BLOCK_SIZE = 16;
 25→    private static final int KEY_512_BYTES = 64;
 26→
 27→    /** K1: first 32 bytes — used for CMAC (AES-256-CMAC). */
 28→    private final byte[] cmacKey;
 29→    /** K2: last 32 bytes — used for AES-CTR encryption. */
 30→    private final byte[] ctrKey;
 31→
 32→    /**
 33→     * Creates an AES-SIV encryptor using the given key holder.
 34→     *
 35→     * @param keyHolder the key holder providing a 512-bit (64-byte) key
 36→     * @throws IllegalArgumentException if key length is not 64 bytes
 37→     */
 38→    public AesSivEncryptor(EncryptionKeyHolder keyHolder) {
 39→        Objects.requireNonNull(keyHolder, "keyHolder must not be null");
 40→        if (keyHolder.keyLength() != KEY_512_BYTES) {
 41→            throw new IllegalArgumentException(
 42→                    "AES-SIV requires a 512-bit (64-byte) key, got " + keyHolder.keyLength());
 43→        }
 44→        final byte[] fullKey = keyHolder.getKeyBytes();
 45→        this.cmacKey = Arrays.copyOfRange(fullKey, 0, 32);
 46→        this.ctrKey = Arrays.copyOfRange(fullKey, 32, 64);
 47→        Arrays.fill(fullKey, (byte) 0);
 48→    }
 49→
 50→    /**
 51→     * Encrypts the plaintext deterministically with optional associated data.
 52→     *
 53→     * @param plaintext the data to encrypt; must not be null
 54→     * @param associatedData optional associated data for IV derivation; may be null
 55→     * @return the ciphertext as {@code [16-byte IV || encrypted bytes]}
 56→     */
 57→    public byte[] encrypt(byte[] plaintext, byte[] associatedData) {
 58→        Objects.requireNonNull(plaintext, "plaintext must not be null");
 59→        final byte[] ad = associatedData != null ? associatedData : new byte[0];
 60→
 61→        final byte[] iv = s2v(ad, plaintext);
 62→        final byte[] encrypted = aesCtr(ctrKey, iv, plaintext);
 63→
 64→        final byte[] result = new byte[BLOCK_SIZE + encrypted.length];
 65→        System.arraycopy(iv, 0, result, 0, BLOCK_SIZE);
 66→        System.arraycopy(encrypted, 0, result, BLOCK_SIZE, encrypted.length);
 67→        return result;
 68→    }
 69→
 70→    /**
 71→     * Decrypts AES-SIV ciphertext and verifies the synthetic IV.
 72→     *
 73→     * @param ciphertext the data to decrypt (IV || encrypted bytes); must not be null
 74→     * @param associatedData the associated data used during encryption; may be null
 75→     * @return the plaintext bytes
 76→     * @throws IllegalArgumentException if ciphertext is too short
 77→     * @throws SecurityException if IV verification fails (wrong key or tampered data)
 78→     */
 79→    public byte[] decrypt(byte[] ciphertext, byte[] associatedData) {
 80→        Objects.requireNonNull(ciphertext, "ciphertext must not be null");
 81→        if (ciphertext.length < BLOCK_SIZE) {
 82→            throw new IllegalArgumentException("Ciphertext too short: minimum " + BLOCK_SIZE
 83→                    + " bytes, got " + ciphertext.length);
 84→        }
 85→        final byte[] ad = associatedData != null ? associatedData : new byte[0];
 86→
 87→        final byte[] iv = Arrays.copyOfRange(ciphertext, 0, BLOCK_SIZE);
 88→        final byte[] encrypted = Arrays.copyOfRange(ciphertext, BLOCK_SIZE, ciphertext.length);
 89→        final byte[] plaintext = aesCtr(ctrKey, iv, encrypted);
 90→
 91→        // Verify: recompute S2V and check it matches the extracted IV
 92→        final byte[] recomputedIv = s2v(ad, plaintext);
 93→        if (!Arrays.equals(iv, recomputedIv)) {
 94→            throw new SecurityException(
 95→                    "AES-SIV IV verification failed: wrong key or tampered data");
 96→        }
 97→        return plaintext;
 98→    }
 99→
100→    // ── S2V (RFC 5297 Section 2.4) ──────────────────────────────────────────
101→
102→    /**
103→     * S2V: computes the synthetic IV from associated data and plaintext. With one AD string S1 and
104→     * plaintext Sn: D = CMAC(K, <zero>) D = dbl(D) XOR CMAC(K, S1) [for AD] if len(Sn) >= 128: T =
105→     * Sn xorend D else: T = dbl(D) XOR pad(Sn) return CMAC(K, T)
106→     */
107→    private byte[] s2v(byte[] ad, byte[] plaintext) {
108→        // D = CMAC(zero block)
109→        byte[] d = cmac(cmacKey, new byte[BLOCK_SIZE]);
110→
111→        // Process AD: D = dbl(D) XOR CMAC(ad)
112→        d = dbl(d);
113→        final byte[] cmacAd = cmac(cmacKey, ad);
114→        xorInPlace(d, cmacAd);
115→
116→        // Process plaintext (Sn)
117→        final byte[] t;
118→        if (plaintext.length >= BLOCK_SIZE) {
119→            // T = Sn xorend D — XOR D into the last 16 bytes of Sn
120→            t = Arrays.copyOf(plaintext, plaintext.length);
121→            final int offset = t.length - BLOCK_SIZE;
122→            for (int i = 0; i < BLOCK_SIZE; i++) {
123→                t[offset + i] ^= d[i];
124→            }
125→        } else {
126→            // T = dbl(D) XOR pad(Sn)
127→            d = dbl(d);
128→            t = pad(plaintext);
129→            xorInPlace(t, d);
130→        }
131→
132→        return cmac(cmacKey, t);
133→    }
134→
135→    // ── CMAC (RFC 4493) via AES/ECB ─────────────────────────────────────────
136→
137→    /**
138→     * AES-CMAC per RFC 4493, implemented using AES/ECB/NoPadding.
139→     */
140→    private static byte[] cmac(byte[] key, byte[] message) {
141→        try {
142→            final Cipher aes = Cipher.getInstance("AES/ECB/NoPadding");
143→            final SecretKeySpec keySpec = new SecretKeySpec(key, "AES");
144→            aes.init(Cipher.ENCRYPT_MODE, keySpec);
145→
146→            // Generate subkeys K1, K2
147→            final byte[] l = aes.doFinal(new byte[BLOCK_SIZE]);
148→            final byte[] k1 = dbl(l);
149→            final byte[] k2 = dbl(k1);
150→
151→            final int n = (message.length + BLOCK_SIZE - 1) / BLOCK_SIZE;
152→            final boolean completeBlock = message.length > 0 && (message.length % BLOCK_SIZE == 0);
153→            final int blocks = Math.max(n, 1);
154→
155→            // Process all blocks except the last with CBC-MAC
156→            final byte[] x = new byte[BLOCK_SIZE];
157→            for (int i = 0; i < blocks - 1; i++) {
158→                for (int j = 0; j < BLOCK_SIZE; j++) {
159→                    x[j] ^= message[i * BLOCK_SIZE + j];
160→                }
161→                final byte[] enc = aes.doFinal(x);
162→                System.arraycopy(enc, 0, x, 0, BLOCK_SIZE);
163→            }
164→
165→            // Last block: XOR with K1 or K2
166→            final byte[] lastBlock;
167→            if (completeBlock) {
168→                lastBlock = Arrays.copyOfRange(message, (blocks - 1) * BLOCK_SIZE,
169→                        blocks * BLOCK_SIZE);
170→                xorInPlace(lastBlock, k1);
171→            } else {
172→                // Pad incomplete block: append 10*
173→                lastBlock = new byte[BLOCK_SIZE];
174→                final int lastStart = (blocks - 1) * BLOCK_SIZE;
175→                final int remaining = message.length - lastStart;
176→                if (remaining > 0) {
177→                    System.arraycopy(message, lastStart, lastBlock, 0, remaining);
178→                }
179→                lastBlock[remaining] = (byte) 0x80;
180→                // rest already 0x00
181→                xorInPlace(lastBlock, k2);
182→            }
183→
184→            xorInPlace(x, lastBlock);
185→            return aes.doFinal(x);
186→        } catch (GeneralSecurityException e) {
187→            throw new IllegalStateException("AES-CMAC computation failed", e);
188→        }
189→    }
190→
191→    // ── AES-CTR encryption ──────────────────────────────────────────────────
192→
193→    /**
194→     * AES-CTR encryption/decryption. Per RFC 5297, the counter is derived from the SIV with bits 63
195→     * and 31 cleared.
196→     */
197→    private static byte[] aesCtr(byte[] key, byte[] iv, byte[] input) {
198→        if (input.length == 0) {
199→            return new byte[0];
200→        }
201→        try {
202→            // Clear bits 63 and 31 of the IV to form the initial counter
203→            final byte[] ctr = Arrays.copyOf(iv, BLOCK_SIZE);
204→            ctr[8] &= 0x7F;
205→            ctr[12] &= 0x7F;
206→
207→            final Cipher aes = Cipher.getInstance("AES/ECB/NoPadding");
208→            final SecretKeySpec keySpec = new SecretKeySpec(key, "AES");
209→            aes.init(Cipher.ENCRYPT_MODE, keySpec);
210→
211→            final byte[] output = new byte[input.length];
212→            final int fullBlocks = input.length / BLOCK_SIZE;
213→            final int remainder = input.length % BLOCK_SIZE;
214→
215→            for (int i = 0; i < fullBlocks; i++) {
216→                final byte[] keystream = aes.doFinal(ctr);
217→                for (int j = 0; j < BLOCK_SIZE; j++) {
218→                    output[i * BLOCK_SIZE + j] = (byte) (input[i * BLOCK_SIZE + j] ^ keystream[j]);
219→                }
220→                incrementCounter(ctr);
221→            }
222→
223→            if (remainder > 0) {
224→                final byte[] keystream = aes.doFinal(ctr);
225→                final int offset = fullBlocks * BLOCK_SIZE;
226→                for (int j = 0; j < remainder; j++) {
227→                    output[offset + j] = (byte) (input[offset + j] ^ keystream[j]);
228→                }
229→            }
230→
231→            return output;
232→        } catch (GeneralSecurityException e) {
233→            throw new IllegalStateException("AES-CTR encryption failed", e);
234→        }
235→    }
236→
237→    // ── Utility ─────────────────────────────────────────────────────────────
238→
239→    /** Doubles a block in GF(2^128) with the irreducible polynomial 0x87. */
240→    private static byte[] dbl(byte[] input) {
241→        assert input.length == BLOCK_SIZE : "dbl input must be 16 bytes";
242→        final byte[] result = new byte[BLOCK_SIZE];
243→        final int carry = (input[0] & 0x80) != 0 ? 0x87 : 0x00;
244→        for (int i = 0; i < BLOCK_SIZE - 1; i++) {
245→            result[i] = (byte) (((input[i] & 0xFF) << 1) | ((input[i + 1] & 0x80) >>> 7));
246→        }
247→        result[BLOCK_SIZE - 1] = (byte) (((input[BLOCK_SIZE - 1] & 0xFF) << 1) ^ carry);
248→        return result;
249→    }
250→
251→    /** Pads a message shorter than BLOCK_SIZE: append 0x80 then zeros. */
252→    private static byte[] pad(byte[] input) {
253→        assert input.length < BLOCK_SIZE : "pad called on full-length input";
254→        final byte[] padded = new byte[BLOCK_SIZE];
255→        System.arraycopy(input, 0, padded, 0, input.length);
256→        padded[input.length] = (byte) 0x80;
257→        return padded;
258→    }
259→
260→    /** XORs src into dst in place: dst[i] ^= src[i]. */
261→    private static void xorInPlace(byte[] dst, byte[] src) {
262→        assert dst.length == src.length : "xorInPlace arrays must be same length";
263→        for (int i = 0; i < dst.length; i++) {
264→            dst[i] ^= src[i];
265→        }
266→    }
267→
268→    /** Increments a 16-byte big-endian counter. */
269→    private static void incrementCounter(byte[] ctr) {
270→        for (int i = BLOCK_SIZE - 1; i >= 0; i--) {
271→            if (++ctr[i] != 0) {
272→                break;
273→            }
274→        }
275→    }
276→}
