 16→
 17→    private static final long DOMAIN = 100;
 18→    private static final long RANGE = 10_000;
 19→
 20→    private EncryptionKeyHolder keyHolder;
 21→
 22→    private static byte[] key256() {
 23→        final byte[] key = new byte[32];
 24→        for (int i = 0; i < key.length; i++) {
 25→            key[i] = (byte) (i + 1);
 26→        }
 27→        return key;
 28→    }
 29→
 30→    private static byte[] key256Alt() {
 31→        final byte[] key = new byte[32];
 32→        for (int i = 0; i < key.length; i++) {
 33→            key[i] = (byte) (i + 0x80);
 34→        }
 35→        return key;
 36→    }
 37→
 38→    @BeforeEach
 39→    void setUp() {
 40→        keyHolder = EncryptionKeyHolder.of(key256());
 41→    }
 42→
 43→    @AfterEach
 44→    void tearDown() {
 45→        keyHolder.close();
 46→    }
 47→
 48→    // ── Round-trip ──────────────────────────────────────────────────────────
 49→
 50→    @Test
 51→    void encryptDecrypt_roundTrip() {
 52→        final BoldyrevaOpeEncryptor encryptor = new BoldyrevaOpeEncryptor(keyHolder, DOMAIN, RANGE);
 53→
 54→        for (long p = 1; p <= 20; p++) {
 55→            final long ct = encryptor.encrypt(p);
 56→            final long recovered = encryptor.decrypt(ct);
 57→            assertEquals(p, recovered, "Round-trip failed for plaintext " + p);
 58→        }
 59→    }
 60→
 61→    @Test
 62→    void encryptDecrypt_boundaryValues() {
 63→        final BoldyrevaOpeEncryptor encryptor = new BoldyrevaOpeEncryptor(keyHolder, DOMAIN, RANGE);
 64→
 65→        final long ctFirst = encryptor.encrypt(1);
 66→        assertEquals(1, encryptor.decrypt(ctFirst));
 67→
 68→        final long ctLast = encryptor.encrypt(DOMAIN);
 69→        assertEquals(DOMAIN, encryptor.decrypt(ctLast));
 70→    }
 71→
 72→    // ── Order preservation ──────────────────────────────────────────────────
 73→
 74→    @Test
 75→    void encrypt_preservesOrder() {
 76→        final BoldyrevaOpeEncryptor encryptor = new BoldyrevaOpeEncryptor(keyHolder, DOMAIN, RANGE);
 77→
 78→        long prevCt = Long.MIN_VALUE;
 79→        for (long p = 1; p <= DOMAIN; p++) {
 80→            final long ct = encryptor.encrypt(p);
 81→            assertTrue(ct > prevCt, "Order not preserved: encrypt(" + (p - 1) + ")=" + prevCt
 82→                    + " >= encrypt(" + p + ")=" + ct);
 83→            prevCt = ct;
 84→        }
 85→    }
