 99→    // ── Different key ───────────────────────────────────────────────────────
100→
101→    @Test
102→    void encrypt_differentKey_producesDifferentCiphertext() {
103→        final BoldyrevaOpeEncryptor enc1 = new BoldyrevaOpeEncryptor(keyHolder, DOMAIN, RANGE);
104→        final long ct1 = enc1.encrypt(50);
105→
106→        try (final EncryptionKeyHolder otherKey = EncryptionKeyHolder.of(key256Alt())) {
107→            final BoldyrevaOpeEncryptor enc2 = new BoldyrevaOpeEncryptor(otherKey, DOMAIN, RANGE);
108→            final long ct2 = enc2.encrypt(50);
109→
110→            assertNotEquals(ct1, ct2, "Different keys should produce different ciphertext");
111→        }
112→    }
113→
114→    // ── Ciphertext range ────────────────────────────────────────────────────
115→
116→    @Test
117→    void encrypt_ciphertextWithinRange() {
118→        final BoldyrevaOpeEncryptor encryptor = new BoldyrevaOpeEncryptor(keyHolder, DOMAIN, RANGE);
119→
120→        for (long p = 1; p <= DOMAIN; p++) {
121→            final long ct = encryptor.encrypt(p);
122→            assertTrue(ct >= 1 && ct <= RANGE,
123→                    "Ciphertext " + ct + " out of range [1.." + RANGE + "]");
124→        }
125→    }
126→
127→    // ── Input validation ────────────────────────────────────────────────────
128→
129→    @Test
130→    void encrypt_plaintextBelowDomain_throwsIllegalArgumentException() {
131→        final BoldyrevaOpeEncryptor encryptor = new BoldyrevaOpeEncryptor(keyHolder, DOMAIN, RANGE);
