  2→
  3→import static org.junit.jupiter.api.Assertions.*;
  4→
  5→import jlsm.table.internal.DcpeSapEncryptor;
  6→import jlsm.table.internal.EncryptionKeyHolder;
  7→
  8→import org.junit.jupiter.api.AfterEach;
  9→import org.junit.jupiter.api.BeforeEach;
 10→import org.junit.jupiter.api.Test;
 11→
 12→import java.util.Arrays;
 13→
 14→/**
 15→ * Tests for {@link DcpeSapEncryptor}: distance-comparison-preserving encryption
 16→ * (Scale-And-Perturb).
 17→ */
 18→class DcpeSapEncryptorTest {
 19→
 20→    private static final int DIMS = 8;
 21→
 22→    private EncryptionKeyHolder keyHolder;
 23→
 24→    private static byte[] key256() {
 25→        final byte[] key = new byte[32];
 26→        for (int i = 0; i < key.length; i++) {
 27→            key[i] = (byte) (i + 1);
 28→        }
 29→        return key;
 30→    }
 31→
 32→    @BeforeEach
 33→    void setUp() {
 34→        keyHolder = EncryptionKeyHolder.of(key256());
 35→    }
 36→
 37→    @AfterEach
 38→    void tearDown() {
 39→        keyHolder.close();
 40→    }
 41→
 42→    private static float[] vector(float... values) {
 43→        return values;
 44→    }
 45→
 46→    private static double l2Distance(float[] a, float[] b) {
 47→        assert a.length == b.length;
 48→        double sum = 0.0;
 49→        for (int i = 0; i < a.length; i++) {
 50→            final double d = a[i] - b[i];
 51→            sum += d * d;
 52→        }
 53→        return Math.sqrt(sum);
 54→    }
 55→
 56→    // ── Round-trip ──────────────────────────────────────────────────────────
 57→
 58→    @Test
 59→    void encryptDecrypt_roundTrip() {
 60→        final DcpeSapEncryptor encryptor = new DcpeSapEncryptor(keyHolder, DIMS);
 61→        final float[] original = vector(1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f, 8.0f);
 62→
 63→        final DcpeSapEncryptor.EncryptedVector ev = encryptor.encrypt(original);
 64→        final float[] recovered = encryptor.decrypt(ev.values(), ev.seed());
 65→
 66→        assertArrayEquals(original, recovered, 1e-4f,
 67→                "Decrypted vector must match original within floating-point tolerance");
 68→    }
 69→
 70→    @Test
 71→    void encryptDecrypt_roundTrip_zeroVector() {
 72→        final DcpeSapEncryptor encryptor = new DcpeSapEncryptor(keyHolder, DIMS);
 73→        final float[] original = new float[DIMS];
 74→
 75→        final DcpeSapEncryptor.EncryptedVector ev = encryptor.encrypt(original);
 76→        final float[] recovered = encryptor.decrypt(ev.values(), ev.seed());
 77→
 78→        assertArrayEquals(original, recovered, 1e-4f);
 79→    }
 80→
 81→    // ── Dimensionality preservation ─────────────────────────────────────────
 82→
 83→    @Test
 84→    void encrypt_preservesDimensionality() {
 85→        final DcpeSapEncryptor encryptor = new DcpeSapEncryptor(keyHolder, DIMS);
 86→        final float[] original = vector(1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f, 8.0f);
 87→
 88→        final DcpeSapEncryptor.EncryptedVector ev = encryptor.encrypt(original);
 89→
 90→        assertEquals(DIMS, ev.values().length,
 91→                "Encrypted vector must have same dimensionality as input");
 92→    }
 93→
 94→    // ── Distance approximate preservation ───────────────────────────────────
 95→
 96→    @Test
 97→    void encrypt_approximatelyPreservesDistanceOrdering() {
 98→        final DcpeSapEncryptor encryptor = new DcpeSapEncryptor(keyHolder, 3);
 99→        final float[] a = vector(0.0f, 0.0f, 0.0f);
100→        final float[] b = vector(1.0f, 0.0f, 0.0f); // close to a
101→        final float[] c = vector(10.0f, 10.0f, 10.0f); // far from a
102→
103→        final DcpeSapEncryptor.EncryptedVector ea = encryptor.encrypt(a);
104→        final DcpeSapEncryptor.EncryptedVector eb = encryptor.encrypt(b);
105→        final DcpeSapEncryptor.EncryptedVector ec = encryptor.encrypt(c);
106→
107→        final double distAB = l2Distance(ea.values(), eb.values());
108→        final double distAC = l2Distance(ea.values(), ec.values());
109→
110→        assertTrue(distAB < distAC, "Encrypted distance(a,b)=" + distAB
111→                + " should be < distance(a,c)=" + distAC + " (approximate distance preservation)");
112→    }
113→
114→    // ── Non-determinism ─────────────────────────────────────────────────────
115→
116→    @Test
117→    void encrypt_differentSeedsPerEncryption() {
118→        final DcpeSapEncryptor encryptor = new DcpeSapEncryptor(keyHolder, DIMS);
119→        final float[] original = vector(1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f, 8.0f);
120→
121→        final DcpeSapEncryptor.EncryptedVector ev1 = encryptor.encrypt(original);
122→        final DcpeSapEncryptor.EncryptedVector ev2 = encryptor.encrypt(original);
123→
124→        assertNotEquals(ev1.seed(), ev2.seed(), "Each encryption should use a different seed");
125→        assertFalse(Arrays.equals(ev1.values(), ev2.values()),
126→                "Different seeds should produce different encrypted values");
127→    }
128→
129→    // ── Encrypted vector usable for distance computation ────────────────────
130→
131→    @Test
132→    void encryptedVector_hasFloatArrayFormat() {
133→        final DcpeSapEncryptor encryptor = new DcpeSapEncryptor(keyHolder, DIMS);
134→        final float[] original = vector(1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f, 8.0f);
135→
136→        final DcpeSapEncryptor.EncryptedVector ev = encryptor.encrypt(original);
137→
138→        assertNotNull(ev.values());
139→        assertEquals(DIMS, ev.values().length);
140→        // Verify values are finite (usable for distance computation)
141→        for (final float v : ev.values()) {
142→            assertTrue(Float.isFinite(v), "Encrypted value must be finite: " + v);
143→        }
144→    }
145→
146→    // ── Input validation ────────────────────────────────────────────────────
147→
148→    @Test
149→    void encrypt_wrongDimensions_throwsIllegalArgumentException() {
150→        final DcpeSapEncryptor encryptor = new DcpeSapEncryptor(keyHolder, DIMS);
151→        assertThrows(IllegalArgumentException.class, () -> encryptor.encrypt(new float[DIMS + 1]));
152→    }
153→
154→    @Test
155→    void encrypt_nullVector_throwsNullPointerException() {
156→        final DcpeSapEncryptor encryptor = new DcpeSapEncryptor(keyHolder, DIMS);
157→        assertThrows(NullPointerException.class, () -> encryptor.encrypt(null));
158→    }
159→
160→    @Test
161→    void constructor_rejectsZeroDimensions() {
162→        assertThrows(IllegalArgumentException.class, () -> new DcpeSapEncryptor(keyHolder, 0));
163→    }
164→
165→    @Test
166→    void constructor_rejectsNegativeDimensions() {
167→        assertThrows(IllegalArgumentException.class, () -> new DcpeSapEncryptor(keyHolder, -1));
168→    }
169→}
