  1→package jlsm.table.internal;
  2→
  3→import java.nio.charset.StandardCharsets;
  4→import java.util.Arrays;
  5→import java.util.List;
  6→
  7→import jlsm.table.EncryptionSpec;
  8→import jlsm.table.FieldDefinition;
  9→import jlsm.table.JlsmSchema;
 10→
 11→/**
 12→ * Dispatch table mapping field positions to their encryption/decryption functions. Constructed once
 13→ * at serializer creation time; immutable and thread-safe after construction.
 14→ *
 15→ * <p>
 16→ * For each field in the schema, checks its {@link EncryptionSpec} and builds the appropriate
 17→ * encryptor/decryptor pair. If the key holder is {@code null}, all entries are {@code null} (no
 18→ * encryption).
 19→ *
 20→ * <p>
 21→ * Governed by: .decisions/field-encryption-api-design/adr.md
 22→ */
 23→public final class FieldEncryptionDispatch {
 24→
 25→    private final FieldEncryptor[] encryptors;
 26→    private final FieldDecryptor[] decryptors;
 27→
 28→    /**
 29→     * Encrypts a byte array field value.
 30→     */
 31→    @FunctionalInterface
 32→    public interface FieldEncryptor {
 33→        byte[] encrypt(byte[] plaintext);
 34→    }
 35→
 36→    /**
 37→     * Decrypts a byte array field value.
 38→     */
 39→    @FunctionalInterface
 40→    public interface FieldDecryptor {
 41→        byte[] decrypt(byte[] ciphertext);
 42→    }
 43→
 44→    /**
 45→     * Constructs a dispatch table for the given schema and key holder.
 46→     *
 47→     * @param schema the schema describing the document structure; must not be null
 48→     * @param keyHolder the key holder providing encryption keys; may be null (no encryption)
 49→     */
 50→    public FieldEncryptionDispatch(JlsmSchema schema, EncryptionKeyHolder keyHolder) {
 51→        assert schema != null : "schema must not be null";
 52→
 53→        final List<FieldDefinition> fields = schema.fields();
 54→        final int fieldCount = fields.size();
 55→        this.encryptors = new FieldEncryptor[fieldCount];
 56→        this.decryptors = new FieldDecryptor[fieldCount];
 57→
 58→        if (keyHolder == null) {
 59→            // No encryption — all entries remain null
 60→            return;
 61→        }
 62→
 63→        for (int i = 0; i < fieldCount; i++) {
 64→            final FieldDefinition fd = fields.get(i);
 65→            final EncryptionSpec spec = fd.encryption();
 66→
 67→            switch (spec) {
 68→                case EncryptionSpec.None _ -> {
 69→                    // No encryption for this field
 70→                }
 71→                case EncryptionSpec.Deterministic _ -> {
 72→                    // AES-SIV requires a 64-byte key. If the table key is 32 bytes,
 73→                    // derive a 64-byte key by repeating it.
 74→                    final EncryptionKeyHolder sivKeyHolder;
 75→                    if (keyHolder.keyLength() == 32) {
 76→                        final byte[] halfKey = keyHolder.getKeyBytes();
 77→                        final byte[] sivKey = new byte[64];
 78→                        System.arraycopy(halfKey, 0, sivKey, 0, 32);
 79→                        System.arraycopy(halfKey, 0, sivKey, 32, 32);
 80→                        Arrays.fill(halfKey, (byte) 0);
 81→                        sivKeyHolder = EncryptionKeyHolder.of(sivKey);
 82→                    } else {
 83→                        sivKeyHolder = keyHolder;
 84→                    }
 85→                    final AesSivEncryptor siv = new AesSivEncryptor(sivKeyHolder);
 86→                    final byte[] associatedData = fd.name().getBytes(StandardCharsets.UTF_8);
 87→                    encryptors[i] = plaintext -> siv.encrypt(plaintext, associatedData);
 88→                    decryptors[i] = ciphertext -> siv.decrypt(ciphertext, associatedData);
 89→                }
 90→                case EncryptionSpec.OrderPreserving _ -> {
 91→                    // OrderPreserving requires domain/range configuration.
 92→                    // For generic byte-level dispatch, use long-based OPE.
 93→                    final BoldyrevaOpeEncryptor ope = new BoldyrevaOpeEncryptor(keyHolder,
 94→                            Long.MAX_VALUE / 2, Long.MAX_VALUE);
 95→                    encryptors[i] = plaintext -> opeEncryptBytes(ope, plaintext);
 96→                    decryptors[i] = ciphertext -> opeDecryptBytes(ope, ciphertext);
 97→                }
 98→                case EncryptionSpec.DistancePreserving _ -> {
 99→                    // DistancePreserving operates on float[] vectors, not byte[].
100→                    // Handled separately in the serializer. Leave null for byte dispatch.
101→                }
102→                case EncryptionSpec.Opaque _ -> {
103→                    // AES-GCM requires a 32-byte key. If the table key is 64 bytes,
104→                    // derive a 32-byte sub-key from the first half.
105→                    final EncryptionKeyHolder gcmKeyHolder;
106→                    if (keyHolder.keyLength() == 64) {
107→                        final byte[] fullKey = keyHolder.getKeyBytes();
108→                        final byte[] gcmKey = Arrays.copyOfRange(fullKey, 0, 32);
109→                        Arrays.fill(fullKey, (byte) 0);
110→                        gcmKeyHolder = EncryptionKeyHolder.of(gcmKey);
111→                    } else {
112→                        gcmKeyHolder = keyHolder;
113→                    }
114→                    final AesGcmEncryptor gcm = new AesGcmEncryptor(gcmKeyHolder);
115→                    encryptors[i] = gcm::encrypt;
116→                    decryptors[i] = gcm::decrypt;
117→                }
118→            }
119→        }
120→    }
121→
122→    /**
123→     * Returns the encryptor for the field at the given index, or {@code null} if no encryption is
124→     * configured.
125→     *
126→     * @param fieldIndex the zero-based field index
127→     * @return the encryptor, or null
128→     */
129→    public FieldEncryptor encryptorFor(int fieldIndex) {
130→        assert fieldIndex >= 0 && fieldIndex < encryptors.length
131→                : "fieldIndex out of bounds: " + fieldIndex;
132→        return encryptors[fieldIndex];
133→    }
134→
135→    /**
136→     * Returns the decryptor for the field at the given index, or {@code null} if no encryption is
137→     * configured.
138→     *
139→     * @param fieldIndex the zero-based field index
140→     * @return the decryptor, or null
141→     */
142→    public FieldDecryptor decryptorFor(int fieldIndex) {
143→        assert fieldIndex >= 0 && fieldIndex < decryptors.length
144→                : "fieldIndex out of bounds: " + fieldIndex;
145→        return decryptors[fieldIndex];
146→    }
147→
148→    // -- OPE byte helpers -------------------------------------------------
149→
150→    /**
151→     * Encodes a byte[] as a positive long, encrypts with OPE, returns the encrypted long as bytes.
152→     */
153→    private static byte[] opeEncryptBytes(BoldyrevaOpeEncryptor ope, byte[] plaintext) {
154→        final long value = bytesToPositiveLong(plaintext);
155→        final long encrypted = ope.encrypt(value);
156→        return longToBytes(encrypted);
157→    }
158→
159→    /**
160→     * Decrypts OPE ciphertext bytes back to the original byte[] representation.
161→     */
162→    private static byte[] opeDecryptBytes(BoldyrevaOpeEncryptor ope, byte[] ciphertext) {
163→        final long encValue = bytesTo8ByteLong(ciphertext);
164→        final long decrypted = ope.decrypt(encValue);
165→        return positiveLongToBytes(decrypted);
166→    }
167→
168→    /**
169→     * Converts up to 6 bytes of data into a positive long in [1..Long.MAX_VALUE/2]. Format: first
170→     * byte = original length, followed by up to 6 data bytes packed into a long.
171→     */
172→    private static long bytesToPositiveLong(byte[] data) {
173→        assert data != null : "data must not be null";
174→        if (data.length > 6) {
175→            throw new IllegalArgumentException(
176→                    "OPE byte encryption supports at most 6 bytes of data, got " + data.length);
177→        }
178→        long result = 1; // ensure positive, minimum = 1
179→        result += ((long) data.length) << 48;
180→        for (int i = 0; i < data.length; i++) {
181→            result += ((long) (data[i] & 0xFF)) << (40 - i * 8);
182→        }
183→        return result;
184→    }
185→
186→    private static byte[] positiveLongToBytes(long value) {
187→        value -= 1; // undo the +1 offset
188→        final int len = (int) ((value >>> 48) & 0xFF);
189→        final byte[] result = new byte[len];
190→        for (int i = 0; i < len; i++) {
191→            result[i] = (byte) ((value >>> (40 - i * 8)) & 0xFF);
192→        }
193→        return result;
194→    }
195→
196→    private static byte[] longToBytes(long value) {
197→        final byte[] buf = new byte[8];
198→        for (int i = 0; i < 8; i++) {
199→            buf[i] = (byte) (value >>> (56 - i * 8));
200→        }
201→        return buf;
202→    }
203→
204→    private static long bytesTo8ByteLong(byte[] buf) {
205→        assert buf.length == 8 : "expected 8 bytes for long";
206→        long result = 0;
207→        for (int i = 0; i < 8; i++) {
208→            result |= ((long) (buf[i] & 0xFF)) << (56 - i * 8);
209→        }
210→        return result;
211→    }
212→}
