  1→package jlsm.table.internal;
  2→
  3→import java.nio.ByteBuffer;
  4→import java.security.GeneralSecurityException;
  5→import java.security.MessageDigest;
  6→import java.util.ArrayList;
  7→import java.util.Arrays;
  8→import java.util.List;
  9→import java.util.Objects;
 10→import java.util.concurrent.ConcurrentHashMap;
 11→import java.util.concurrent.atomic.AtomicInteger;
 12→
 13→import javax.crypto.Cipher;
 14→import javax.crypto.Mac;
 15→import javax.crypto.spec.GCMParameterSpec;
 16→import javax.crypto.spec.SecretKeySpec;
 17→
 18→/**
 19→ * Contract: Tier 3 SSE (Searchable Symmetric Encryption) encrypted inverted index based on Curtmola
 20→ * SSE-2 / Dyn2Lev. For each term, derives a search token {@code Tw = PRF(K, term)}, encrypts the
 21→ * document ID and stores it in a {@link ConcurrentHashMap} keyed by a hash derived from the token
 22→ * and a per-term state counter.
 23→ *
 24→ * <p>
 25→ * Search: caller submits Tw, index iterates over state counters 0..N, derives addresses, collects
 26→ * all matching encrypted docIds, decrypts and returns them.
 27→ *
 28→ * <p>
 29→ * Forward privacy: each add operation increments a per-term state counter, producing a new storage
 30→ * address. This prevents linking new additions to previous ones.
 31→ *
 32→ * <p>
 33→ * Governed by: .decisions/encrypted-index-strategy/adr.md
 34→ */
 35→public final class SseEncryptedIndex {
 36→
 37→    /** Tag length for AES-GCM encryption of docIds. */
 38→    private static final int GCM_TAG_BITS = 128;
 39→    /** IV size for AES-GCM. */
 40→    private static final int GCM_IV_BYTES = 12;
 41→    /** Marker byte for a live (non-deleted) entry. */
 42→    private static final byte LIVE_MARKER = (byte) 0x01;
 43→    /** Marker byte for a deleted entry. */
 44→    private static final byte DELETED_MARKER = (byte) 0x00;
 45→
 46→    /** Key material for HMAC-based PRF. */
 47→    private final byte[] prfKey;
 48→    /** Key material for AES-GCM docId encryption. */
 49→    private final byte[] encKey;
 50→
 51→    /**
 52→     * Backing store: address (derived from token + counter) -> encrypted entry. Each entry is:
 53→     * [1-byte live/deleted marker][GCM-IV][encrypted docId + tag].
 54→     */
 55→    private final ConcurrentHashMap<ByteArrayKey, byte[]> store;
 56→
 57→    /** Per-term state counter for forward privacy. */
 58→    private final ConcurrentHashMap<String, AtomicInteger> termCounters;
 59→
 60→    /**
 61→     * Creates a new SSE encrypted index with the given key.
 62→     *
 63→     * @param keyHolder the key holder for PRF and posting list encryption
 64→     * @throws NullPointerException if keyHolder is null
 65→     */
 66→    public SseEncryptedIndex(EncryptionKeyHolder keyHolder) {
 67→        Objects.requireNonNull(keyHolder, "keyHolder must not be null");
 68→        final byte[] keyBytes = keyHolder.getKeyBytes();
 69→
 70→        // Derive two sub-keys from the master key via HMAC with different labels
 71→        this.prfKey = deriveSubKey(keyBytes, "SSE-PRF-KEY");
 72→        this.encKey = deriveSubKey(keyBytes, "SSE-ENC-KEY");
 73→        Arrays.fill(keyBytes, (byte) 0);
 74→
 75→        this.store = new ConcurrentHashMap<>();
 76→        this.termCounters = new ConcurrentHashMap<>();
 77→    }
 78→
 79→    /**
 80→     * Derives a search token for the given term. Token derivation is deterministic:
 81→     * {@code Tw = HMAC-SHA256(prfKey, term)}.
 82→     *
 83→     * @param term the plaintext search term
 84→     * @return the search token bytes (32 bytes)
 85→     * @throws NullPointerException if term is null
 86→     */
 87→    public byte[] deriveToken(String term) {
 88→        Objects.requireNonNull(term, "term must not be null");
 89→        return hmacSha256(prfKey, term.getBytes(java.nio.charset.StandardCharsets.UTF_8));
 90→    }
 91→
 92→    /**
 93→     * Adds a document to the posting list for the given term. Each add increments a per-term state
 94→     * counter for forward privacy, producing a unique storage address.
 95→     *
 96→     * @param term the plaintext term
 97→     * @param docId the document identifier
 98→     * @throws NullPointerException if term or docId is null
 99→     */
100→    public void add(String term, byte[] docId) {
101→        Objects.requireNonNull(term, "term must not be null");
102→        Objects.requireNonNull(docId, "docId must not be null");
103→
104→        final byte[] token = deriveToken(term);
105→
106→        // Increment state counter for forward privacy
107→        final AtomicInteger counter = termCounters.computeIfAbsent(term, k -> new AtomicInteger(0));
108→        final int stateNum = counter.getAndIncrement();
109→
110→        // Derive storage address from token + counter
111→        final byte[] address = deriveAddress(token, stateNum);
112→
113→        // Encrypt the docId
114→        final byte[] encryptedEntry = encryptDocId(docId, address);
115→
116→        store.put(new ByteArrayKey(address), encryptedEntry);
117→    }
118→
119→    /**
120→     * Removes a document from the posting list for the given term. Marks the entry as deleted by
121→     * scanning all state counter positions and finding the matching docId.
122→     *
123→     * @param term the plaintext term
124→     * @param docId the document identifier to remove
125→     * @throws NullPointerException if term or docId is null
126→     */
127→    public void delete(String term, byte[] docId) {
128→        Objects.requireNonNull(term, "term must not be null");
129→        Objects.requireNonNull(docId, "docId must not be null");
130→
131→        final byte[] token = deriveToken(term);
132→        final AtomicInteger counter = termCounters.get(term);
133→        if (counter == null) {
134→            return; // Term never added — nothing to delete
135→        }
136→
137→        final int maxCounter = counter.get();
138→        for (int i = 0; i < maxCounter; i++) {
139→            final byte[] address = deriveAddress(token, i);
140→            final ByteArrayKey key = new ByteArrayKey(address);
141→            final byte[] entry = store.get(key);
142→            if (entry == null || entry[0] == DELETED_MARKER) {
143→                continue;
144→            }
145→
146→            // Decrypt and check if this is the docId to delete
147→            final byte[] decrypted = decryptDocId(entry, address);
148→            if (decrypted != null && Arrays.equals(decrypted, docId)) {
149→                // Mark as deleted by replacing the live marker
150→                final byte[] deletedEntry = Arrays.copyOf(entry, entry.length);
151→                deletedEntry[0] = DELETED_MARKER;
152→                store.put(key, deletedEntry);
153→                return;
154→            }
155→        }
156→    }
157→
158→    /**
159→     * Searches for documents matching the given search token. Iterates over all state counter
160→     * positions, decrypts live entries, and returns the matching docIds.
161→     *
162→     * @param token the search token (derived via {@link #deriveToken})
163→     * @return the list of matching document identifiers
164→     * @throws NullPointerException if token is null
165→     */
166→    public List<byte[]> search(byte[] token) {
167→        Objects.requireNonNull(token, "token must not be null");
168→
169→        final List<byte[]> results = new ArrayList<>();
170→
171→        // We need to find the term that maps to this token. Since we store counters by term,
172→        // iterate all possible counter values. We scan addresses starting from 0 until we
173→        // hit a miss.
174→        for (int i = 0;; i++) {
175→            final byte[] address = deriveAddress(token, i);
176→            final ByteArrayKey key = new ByteArrayKey(address);
177→            final byte[] entry = store.get(key);
178→            if (entry == null) {
179→                break; // No more entries for this token
180→            }
181→            if (entry[0] == LIVE_MARKER) {
182→                final byte[] decrypted = decryptDocId(entry, address);
183→                if (decrypted != null) {
184→                    results.add(decrypted);
185→                }
186→            }
187→        }
188→
189→        return results;
190→    }
191→
192→    // ── Internal helpers ────────────────────────────────────────────────────
193→
194→    /**
195→     * Derives a storage address from a token and state counter:
196→     * {@code address = HMAC-SHA256(token, counter_bytes)}.
197→     */
198→    private byte[] deriveAddress(byte[] token, int counter) {
199→        final byte[] counterBytes = ByteBuffer.allocate(4).putInt(counter).array();
200→        return hmacSha256(token, counterBytes);
201→    }
202→
203→    /**
204→     * Encrypts a docId using AES-GCM with the address as additional authenticated data. Format:
205→     * [1-byte live marker][12-byte IV][encrypted docId + 16-byte GCM tag].
206→     */
207→    private byte[] encryptDocId(byte[] docId, byte[] address) {
208→        try {
209→            // Derive a deterministic IV from the address (first 12 bytes of hash)
210→            final byte[] ivSource = MessageDigest.getInstance("SHA-256").digest(address);
211→            final byte[] iv = Arrays.copyOf(ivSource, GCM_IV_BYTES);
212→
213→            final Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
214→            final SecretKeySpec keySpec = new SecretKeySpec(encKey, 0, Math.min(encKey.length, 32),
215→                    "AES");
216→            cipher.init(Cipher.ENCRYPT_MODE, keySpec, new GCMParameterSpec(GCM_TAG_BITS, iv));
217→            cipher.updateAAD(address);
218→
219→            final byte[] encrypted = cipher.doFinal(docId);
220→
221→            // [marker][iv][encrypted + tag]
222→            final byte[] entry = new byte[1 + GCM_IV_BYTES + encrypted.length];
223→            entry[0] = LIVE_MARKER;
224→            System.arraycopy(iv, 0, entry, 1, GCM_IV_BYTES);
225→            System.arraycopy(encrypted, 0, entry, 1 + GCM_IV_BYTES, encrypted.length);
226→            return entry;
227→        } catch (GeneralSecurityException e) {
228→            throw new IllegalStateException("AES-GCM encryption failed", e);
229→        }
230→    }
231→
232→    /**
233→     * Decrypts a docId from an encrypted entry.
234→     */
235→    private byte[] decryptDocId(byte[] entry, byte[] address) {
236→        assert entry != null : "entry must not be null";
237→        assert entry.length > 1 + GCM_IV_BYTES : "entry too short for decryption";
238→
239→        try {
240→            final byte[] iv = Arrays.copyOfRange(entry, 1, 1 + GCM_IV_BYTES);
241→            final byte[] encrypted = Arrays.copyOfRange(entry, 1 + GCM_IV_BYTES, entry.length);
242→
243→            final Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
244→            final SecretKeySpec keySpec = new SecretKeySpec(encKey, 0, Math.min(encKey.length, 32),
245→                    "AES");
246→            cipher.init(Cipher.DECRYPT_MODE, keySpec, new GCMParameterSpec(GCM_TAG_BITS, iv));
247→            cipher.updateAAD(address);
248→
249→            return cipher.doFinal(encrypted);
250→        } catch (GeneralSecurityException e) {
251→            // Decryption failure — possibly a deleted/corrupted entry
252→            return null;
253→        }
254→    }
255→
256→    /**
257→     * Derives a sub-key from the master key using HMAC-SHA256 with a label.
258→     */
259→    private static byte[] deriveSubKey(byte[] masterKey, String label) {
260→        return hmacSha256(masterKey, label.getBytes(java.nio.charset.StandardCharsets.UTF_8));
261→    }
262→
263→    /**
264→     * Computes HMAC-SHA256.
265→     */
266→    private static byte[] hmacSha256(byte[] key, byte[] data) {
267→        try {
268→            final Mac mac = Mac.getInstance("HmacSHA256");
269→            mac.init(new SecretKeySpec(key, "HmacSHA256"));
270→            return mac.doFinal(data);
271→        } catch (GeneralSecurityException e) {
272→            throw new IllegalStateException("HMAC-SHA256 computation failed", e);
273→        }
274→    }
275→
276→    /**
277→     * A byte-array wrapper that provides proper equals/hashCode semantics for use as a
278→     * ConcurrentHashMap key.
279→     */
280→    private record ByteArrayKey(byte[] data) {
281→
282→        @Override
283→        public boolean equals(Object obj) {
284→            return obj instanceof ByteArrayKey other && Arrays.equals(data, other.data);
285→        }
286→
287→        @Override
288→        public int hashCode() {
289→            return Arrays.hashCode(data);
290→        }
291→    }
292→}
