  3→import java.nio.ByteBuffer;
  4→import java.util.Objects;
  5→
  6→/**
  7→ * Contract: Tier 2 position-aware posting format for encrypted full-text search. Extends inverted
  8→ * index postings with OPE-encrypted term positions. Encodes a document ID and its term positions
  9→ * into a byte sequence where positions are OPE-encrypted, enabling phrase queries (consecutive OPE
 10→ * positions) and proximity queries (position difference within threshold).
 11→ *
 12→ * <p>
 13→ * Encoding format: {@code [4-byte docId length][docId bytes][4-byte position count]
 14→ * [OPE-encrypted positions as 8-byte big-endian longs]}.
 15→ *
 16→ * <p>
 17→ * Governed by: .decisions/encrypted-index-strategy/adr.md
 18→ */
 19→public final class PositionalPostingCodec {
 20→
 21→    /**
 22→     * Minimum posting size: 4 (docId len) + 1 (min docId) + 4 (position count) + 8 (one position).
 23→     */
 24→    private static final int MIN_POSTING_SIZE = 4 + 1 + 4 + 8;
 25→
 26→    private final AesSivEncryptor detEncryptor;
 27→    private final BoldyrevaOpeEncryptor opeEncryptor;
 28→
 29→    /**
 30→     * Creates a positional posting codec with the given encryptors.
 31→     *
 32→     * @param detEncryptor the deterministic encryptor for term values
 33→     * @param opeEncryptor the order-preserving encryptor for term positions
 34→     */
 35→    public PositionalPostingCodec(AesSivEncryptor detEncryptor,
 36→            BoldyrevaOpeEncryptor opeEncryptor) {
 37→        Objects.requireNonNull(detEncryptor, "detEncryptor must not be null");
 38→        Objects.requireNonNull(opeEncryptor, "opeEncryptor must not be null");
 39→        this.detEncryptor = detEncryptor;
 40→        this.opeEncryptor = opeEncryptor;
 41→    }
 42→
 43→    /**
 44→     * Encodes a document ID and its term positions into an encrypted posting entry. Each position
 45→     * is encrypted using OPE to preserve ordering for phrase and proximity queries.
 46→     *
 47→     * @param docId the document identifier; must not be null
 48→     * @param positions the plaintext term positions within the document; must not be null or empty
 49→     * @return the encoded posting bytes
 50→     * @throws NullPointerException if docId or positions is null
 51→     * @throws IllegalArgumentException if positions is empty
 52→     */
 53→    public byte[] encode(byte[] docId, long[] positions) {
 54→        Objects.requireNonNull(docId, "docId must not be null");
 55→        Objects.requireNonNull(positions, "positions must not be null");
 56→        if (positions.length == 0) {
 57→            throw new IllegalArgumentException("positions must not be empty");
 58→        }
 59→
 60→        assert docId.length > 0 : "docId should have at least one byte";
 61→
 62→        // OPE-encrypt each position
 63→        final long[] encryptedPositions = new long[positions.length];
 64→        for (int i = 0; i < positions.length; i++) {
 65→            encryptedPositions[i] = opeEncryptor.encrypt(positions[i]);
 66→        }
 67→
 68→        // Build the encoded posting:
 69→        // [4-byte docId length][docId bytes][4-byte position count][8-byte OPE positions...]
 70→        final int totalSize = 4 + docId.length + 4 + (positions.length * 8);
 71→        final ByteBuffer buffer = ByteBuffer.allocate(totalSize);
 72→        buffer.putInt(docId.length);
 73→        buffer.put(docId);
 74→        buffer.putInt(encryptedPositions.length);
 75→        for (final long encPos : encryptedPositions) {
 76→            buffer.putLong(encPos);
 77→        }
 78→
 79→        assert buffer.remaining() == 0 : "buffer should be fully written";
 80→        return buffer.array();
 81→    }
 82→
 83→    /**
 84→     * Decodes an encrypted posting entry.
 85→     *
 86→     * @param posting the encoded posting bytes; must not be null
 87→     * @return the decoded posting with document ID and OPE-encrypted positions
 88→     * @throws NullPointerException if posting is null
 89→     * @throws IllegalArgumentException if posting is too short or malformed
 90→     */
 91→    public DecodedPosting decode(byte[] posting) {
 92→        Objects.requireNonNull(posting, "posting must not be null");
 93→        if (posting.length < MIN_POSTING_SIZE) {
 94→            throw new IllegalArgumentException("Posting too short: minimum " + MIN_POSTING_SIZE
 95→                    + " bytes, got " + posting.length);
 96→        }
 97→
 98→        final ByteBuffer buffer = ByteBuffer.wrap(posting);
 99→
100→        // Read docId
101→        final int docIdLength = buffer.getInt();
102→        if (docIdLength <= 0 || docIdLength > posting.length - 8) {
103→            throw new IllegalArgumentException("Invalid docId length: " + docIdLength);
104→        }
105→        final byte[] docId = new byte[docIdLength];
106→        buffer.get(docId);
107→
108→        // Read encrypted positions
109→        final int positionCount = buffer.getInt();
110→        if (positionCount <= 0) {
111→            throw new IllegalArgumentException("Invalid position count: " + positionCount);
112→        }
113→        if (buffer.remaining() < positionCount * 8) {
114→            throw new IllegalArgumentException("Posting truncated: expected " + (positionCount * 8)
115→                    + " bytes for positions, got " + buffer.remaining());
116→        }
117→
118→        final long[] encryptedPositions = new long[positionCount];
119→        for (int i = 0; i < positionCount; i++) {
120→            encryptedPositions[i] = buffer.getLong();
121→        }
122→
123→        assert buffer.remaining() == 0 : "buffer should be fully consumed";
124→        return new DecodedPosting(docId, encryptedPositions);
125→    }
126→
127→    /**
128→     * A decoded posting entry containing the document ID and OPE-encrypted positions.
129→     *
130→     * @param docId the document identifier
131→     * @param encryptedPositions the OPE-encrypted term positions (order-preserved)
132→     */
133→    public record DecodedPosting(byte[] docId, long[] encryptedPositions) {
134→    }
135→}
