 43→        assertNull(dispatch.encryptorFor(0), "encryptor should be null when keyHolder is null");
 44→        assertNull(dispatch.encryptorFor(1), "encryptor should be null when keyHolder is null");
 45→        assertNull(dispatch.decryptorFor(0), "decryptor should be null when keyHolder is null");
 46→        assertNull(dispatch.decryptorFor(1), "decryptor should be null when keyHolder is null");
