156→    // ── Thread safety ───────────────────────────────────────────────────
157→
158→    @Test
159→    void encryptorsUsableFromMultipleThreads() throws Exception {
160→        JlsmSchema schema = JlsmSchema.builder("test", 1)
161→                .field("det", FieldType.string(), EncryptionSpec.deterministic()).build();
162→
163→        var dispatch = new FieldEncryptionDispatch(schema, keyHolder);
164→        var encryptor = dispatch.encryptorFor(0);
165→        assertNotNull(encryptor);
166→
167→        byte[] plaintext = "concurrent-test".getBytes();
168→        byte[] expected = encryptor.encrypt(plaintext);
169→
170→        final int threadCount = 4;
171→        CyclicBarrier barrier = new CyclicBarrier(threadCount);
172→        AtomicReference<Throwable> failure = new AtomicReference<>();
173→        Thread[] threads = new Thread[threadCount];
174→
175→        for (int t = 0; t < threadCount; t++) {
176→            threads[t] = new Thread(() -> {
177→                try {
178→                    barrier.await();
179→                    for (int i = 0; i < 50; i++) {
180→                        byte[] ct = encryptor.encrypt(plaintext);
181→                        assertArrayEquals(expected, ct);
182→                    }
183→                } catch (Throwable ex) {
184→                    failure.compareAndSet(null, ex);
185→                }
186→            });
187→            threads[t].start();
188→        }
189→
190→        for (Thread thread : threads) {
191→            thread.join(5000);
192→        }
193→
194→        if (failure.get() != null) {
195→            fail("Thread safety test failed: " + failure.get().getMessage());
196→        }
197→    }
