200→
201→    @Test
202→    void deterministicField_domainSeparationByFieldName() {
203→        JlsmSchema schema = JlsmSchema.builder("test", 1)
204→                .field("field_a", FieldType.string(), EncryptionSpec.deterministic())
205→                .field("field_b", FieldType.string(), EncryptionSpec.deterministic()).build();
