207→        var dispatch = new FieldEncryptionDispatch(schema, keyHolder);
208→
209→        byte[] plaintext = "same-value".getBytes();
210→        byte[] ctA = dispatch.encryptorFor(0).encrypt(plaintext);
211→        byte[] ctB = dispatch.encryptorFor(1).encrypt(plaintext);
212→
213→        assertFalse(Arrays.equals(ctA, ctB),
214→                "Same value under different field names should produce different ciphertext");
215→    }
216→}
