 22→/**
 23→ * Tests for {@link SseEncryptedIndex} — Tier 3 SSE encrypted inverted index.
 24→ *
 25→ * <p>
 26→ * Verifies: token derivation determinism, add/search/delete, forward privacy via state counter,
 27→ * concurrent safety, and error cases.
 28→ */
 29→class SseEncryptedIndexTest {
 30→
 31→    private EncryptionKeyHolder keyHolder;
 32→    private SseEncryptedIndex index;
 33→
 34→    @BeforeEach
 35→    void setUp() {
 36→        final byte[] keyMaterial = new byte[32];
 37→        for (int i = 0; i < 32; i++) {
 38→            keyMaterial[i] = (byte) (i + 0xA0);
 39→        }
 40→        keyHolder = EncryptionKeyHolder.of(keyMaterial);
 41→        index = new SseEncryptedIndex(keyHolder);
 42→    }
 43→
 44→    @AfterEach
 45→    void tearDown() {
 46→        keyHolder.close();
 47→    }
 48→
 49→    // ── Token derivation ───────────────────────────────────────────────────
 50→
 51→    @Test
 52→    void tokenDerivationIsDeterministicForSameTerm() {
 53→        final byte[] token1 = index.deriveToken("hello");
 54→        final byte[] token2 = index.deriveToken("hello");
 55→
 56→        assertArrayEquals(token1, token2, "Same term must always produce the same search token");
 57→    }
 58→
 59→    @Test
 60→    void tokenDerivationDiffersForDifferentTerms() {
 61→        final byte[] tokenHello = index.deriveToken("hello");
 62→        final byte[] tokenWorld = index.deriveToken("world");
 63→
 64→        assertFalse(Arrays.equals(tokenHello, tokenWorld),
 65→                "Different terms must produce different tokens");
 66→    }
 67→
 68→    @Test
 69→    void tokenIsNotEmpty() {
 70→        final byte[] token = index.deriveToken("test");
 71→        assertNotNull(token);
 72→        assertTrue(token.length > 0, "Token must not be empty");
 73→    }
 74→
 75→    // ── Add and search ─────────────────────────────────────────────────────
 76→
 77→    @Test
 78→    void addThenSearchReturnsThatDocId() {
 79→        final byte[] docId = "doc-1".getBytes();
 80→        index.add("term1", docId);
 81→
 82→        final byte[] token = index.deriveToken("term1");
 83→        final List<byte[]> results = index.search(token);
 84→
 85→        assertEquals(1, results.size());
 86→        assertArrayEquals(docId, results.getFirst());
 87→    }
 88→
 89→    @Test
 90→    void multipleDocsForSameTerm() {
 91→        index.add("shared-term", "doc-A".getBytes());
 92→        index.add("shared-term", "doc-B".getBytes());
 93→        index.add("shared-term", "doc-C".getBytes());
 94→
 95→        final byte[] token = index.deriveToken("shared-term");
 96→        final List<byte[]> results = index.search(token);
 97→
 98→        assertEquals(3, results.size());
 99→        final Set<String> docIds = results.stream().map(String::new).collect(Collectors.toSet());
100→        assertTrue(docIds.contains("doc-A"));
101→        assertTrue(docIds.contains("doc-B"));
102→        assertTrue(docIds.contains("doc-C"));
103→    }
104→
105→    @Test
106→    void searchWithWrongTokenReturnsEmpty() {
107→        index.add("realterm", "doc-1".getBytes());
108→
109→        final byte[] wrongToken = index.deriveToken("wrongterm");
110→        final List<byte[]> results = index.search(wrongToken);
111→
112→        assertTrue(results.isEmpty(), "Wrong token should return empty results");
