137→    // ── Delete ─────────────────────────────────────────────────────────────
138→
139→    @Test
140→    void deleteRemovesDocFromResults() {
141→        index.add("term", "doc-1".getBytes());
142→        index.add("term", "doc-2".getBytes());
143→        index.add("term", "doc-3".getBytes());
144→
145→        index.delete("term", "doc-2".getBytes());
146→
147→        final List<byte[]> results = index.search(index.deriveToken("term"));
148→        assertEquals(2, results.size());
149→        final Set<String> docIds = results.stream().map(String::new).collect(Collectors.toSet());
150→        assertTrue(docIds.contains("doc-1"));
151→        assertFalse(docIds.contains("doc-2"));
152→        assertTrue(docIds.contains("doc-3"));
153→    }
154→
155→    @Test
156→    void deleteAllDocsForTermResultsInEmptySearch() {
