 36→        final byte[] keyMaterial = new byte[64];
 37→        for (int i = 0; i < 64; i++) {
 38→            keyMaterial[i] = (byte) (i + 1);
 39→        }
 40→        keyHolder = EncryptionKeyHolder.of(keyMaterial);
 41→        detEncryptor = new AesSivEncryptor(keyHolder);
 42→        opeEncryptor = new BoldyrevaOpeEncryptor(keyHolder, DOMAIN_SIZE, RANGE_SIZE);
 43→        codec = new PositionalPostingCodec(detEncryptor, opeEncryptor);
 44→    }
