 55→        final byte[] docId = "doc-42".getBytes();
 56→        final long[] positions = { 1L, 5L, 10L, 100L };
 57→
 58→        final byte[] encoded = codec.encode(docId, positions);
 59→        assertNotNull(encoded);
 60→        assertTrue(encoded.length > 0);
 61→
 62→        final PositionalPostingCodec.DecodedPosting decoded = codec.decode(encoded);
 63→        assertNotNull(decoded);
