133→        // so enc(10) < enc(11) < enc(12). We can verify the relative differences
134→        // by checking that for consecutive positions a < b, enc(a) < enc(b).
135→        final byte[] docId = "phrase-doc".getBytes();
136→        final long[] phrasePositions = { 10L, 11L, 12L };
137→        final long[] scatteredPositions = { 10L, 50L, 200L };
138→
