140→                .decode(codec.encode(docId, phrasePositions));
141→        final PositionalPostingCodec.DecodedPosting scatteredDecoded = codec
142→                .decode(codec.encode(docId, scatteredPositions));
143→
144→        // Phrase: all consecutive diffs should be equal in OPE space (enc(n+1) - enc(n) is constant
145→        // for consecutive inputs in a well-behaved OPE). At minimum, order is preserved.
146→        final long[] phraseEnc = phraseDecoded.encryptedPositions();
147→        assertTrue(phraseEnc[0] < phraseEnc[1]);
148→        assertTrue(phraseEnc[1] < phraseEnc[2]);
149→
