151→        final long[] scatteredEnc = scatteredDecoded.encryptedPositions();
152→        final long phraseDiff = phraseEnc[2] - phraseEnc[0];
153→        final long scatteredDiff = scatteredEnc[2] - scatteredEnc[0];
154→        assertTrue(scatteredDiff > phraseDiff,
155→                "Scattered positions should have larger OPE gaps than consecutive positions");
156→    }
